# frozen_string_literal: true

# Generated by spec-lang build from module hop.laws (hop/laws.slg). Do not edit: change the spec and build again.

module Hop
  module Laws
    # type Play (hop/laws.slg:8)
    Play = Spec::Type.rules("Play", "hop.world.start", "hop.world.step")

    # law never_inside_a_solid (hop/laws.slg:10)
    # @why the hero is never inside a solid
    def self.never_inside_a_solid(t)
      t.states.all? do |w|
        w.stage.solids.all? { |s| !Hop::Geom.overlaps(Hop::Physics.body(w.player.at), s.box) }
      end
    end

    # law speed_is_bounded (hop/laws.slg:14)
    # @why speeds stay in bounds, so a body never passes through a solid in one tick
    def self.speed_is_bounded(t)
      t.states.all? do |w|
        w.player.vel.x.abs <= Hop::Physics.run_speed &&
          w.player.vel.z.abs <= Hop::Physics.run_speed &&
          (0 - Hop::Physics.max_fall <= (link = w.player.vel.y) && link <= Hop::Physics.jump_speed)
      end
    end

    # law taken_only_grows (hop/laws.slg:19)
    # @why a gem once taken stays taken until the level starts again
    def self.taken_only_grows(t)
      t.steps.all? { |s| s.before.taken.to_a.all? { |g| s.after.taken.include?(g) } }
    end

    # law lives_never_rise (hop/laws.slg:23)
    # @why lives only go down during play
    def self.lives_never_rise(t) = t.steps.all? { |it| it.after.lives <= it.before.lives }

    # law lost_means_no_lives (hop/laws.slg:27)
    # @why no lives left is exactly a lost game
    def self.lost_means_no_lives(t)
      t.states.all? { |w| (w.lives == 0) == (w.mode == Hop::Model::Mode::Lost) }
    end

    # law over_is_final (hop/laws.slg:31)
    # @why a finished game is final: a step is refused and nothing moves
    def self.over_is_final(t)
      t.steps.all? do |s|
        !(s.before.mode != Hop::Model::Mode::Playing) || s.reply.is_a?(Spec::Err) && s.after == s.before
      end
    end

    # law one_tick_per_step (hop/laws.slg:35)
    # @why time moves one tick per accepted step
    def self.one_tick_per_step(t)
      t.steps.all? { |s| !s.reply.is_a?(Spec::Ok) || s.after.ticks == s.before.ticks + 1 }
    end

    # law taken_are_real_gems (hop/laws.slg:39)
    # @why a taken gem is one the level has
    def self.taken_are_real_gems(t)
      t.states.all? { |w| w.taken.to_a.all? { |n| w.stage.gems.any? { |it| it.no == n } } }
    end
  end
end
